def resolve_triple_diagonal_colors(grid):
    """Grid resolution with triple diagonal color constraints"""
    n = len(grid)

    # Count color frequencies
    color_counts = {}
    for r in range(n):
        for c in range(n):
            v = grid[r][c]
            color_counts[v] = color_counts.get(v, 0) + 1

    # Find triple diagonal colors (colors where k=n-1 has at least 3 cells)
    triple_diag_colors = set()
    for c in color_counts:
        if c != 0:  # skip background
            for k in range(n):
                cells = [(r, k - r + n - 1) for r in range(max(0, k + 1 - (n - 1)), min(n, k + 1))]
                if len(cells) >= 3:
                    triple_diag_colors.add(c)

    return list(triple_diag_colors)

